-- otel-demo: the 45 PPL queries as datafusion SQL, one per line in schedule order (t1-01 … t2-26).
-- A `-- SKIP: <reason>` line holds the slot of a query this engine cannot express; the benchmark driver records it as skipped.
SELECT COUNT(*) AS value, date_bin(INTERVAL '1 minute', "startTime") AS ts, "serviceName" FROM otel_spans WHERE "startTime" IS NOT NULL GROUP BY date_bin(INTERVAL '1 minute', "startTime"), "serviceName" ORDER BY ts ASC, "serviceName" ASC LIMIT 10000;
SELECT total, s, t, "serviceName", round((s + t * 0.5) / total, 4) AS apdex FROM (SELECT COUNT(*) AS total, SUM(CASE WHEN "durationInNanos" <= 500000000 THEN 1 ELSE 0 END) AS s, SUM(CASE WHEN "durationInNanos" > 500000000 AND "durationInNanos" <= 2000000000 THEN 1 ELSE 0 END) AS t, "serviceName" FROM otel_spans WHERE kind IN ('SPAN_KIND_SERVER', 'SPAN_KIND_CONSUMER') GROUP BY "serviceName") ORDER BY apdex ASC LIMIT 10000;
SELECT total, affected, name, all_total, all_affected, round(CAST(affected AS DOUBLE) / total, 4) AS rate, round(CAST(all_affected AS DOUBLE) / all_total, 4) AS overall_rate FROM (SELECT total, affected, name, SUM(total) OVER () AS all_total, SUM(affected) OVER () AS all_affected FROM (SELECT COUNT(*) AS total, SUM(CASE WHEN "durationInNanos" > 100000000 THEN 1 ELSE 0 END) AS affected, name FROM otel_spans WHERE "serviceName" = 'frontend' AND kind = 'SPAN_KIND_SERVER' GROUP BY name)) WHERE total >= 20 ORDER BY rate DESC LIMIT 20;
SELECT COUNT(DISTINCT "traceId") AS trace_count, "serviceName" FROM otel_spans GROUP BY "serviceName" ORDER BY trace_count DESC LIMIT 10000;
SELECT COUNT(*) AS span_count, "traceId" FROM otel_spans GROUP BY "traceId" ORDER BY span_count DESC LIMIT 20;
SELECT COUNT(*) AS cnt FROM otel_spans WHERE "serviceName" = 'checkout' AND "endTime" >= '2026-10-16T06:40:00Z';
SELECT * FROM otel_spans ORDER BY "startTime" DESC LIMIT 50;
SELECT COUNT(*) AS spans_with_exception, t_min, "serviceName" FROM (SELECT DISTINCT "traceId", "spanId", t_min, "serviceName" FROM (SELECT "traceId", "spanId", date_bin(INTERVAL '1 minute', "startTime") AS t_min, "serviceName", unnest(events) AS e FROM otel_spans WHERE "startTime" IS NOT NULL) WHERE get_field(e, 'name') = 'exception') GROUP BY t_min, "serviceName" ORDER BY t_min ASC, "serviceName" ASC LIMIT 10000;
SELECT * FROM otel_logs WHERE "traceId" = '59c5c193c46bf6d736d615d2a5ca8001' LIMIT 1000;
SELECT COUNT(*) AS count, date_bin(INTERVAL '1 minute', "eventTime") AS t, "severityText" FROM otel_logs GROUP BY date_bin(INTERVAL '1 minute', "eventTime"), "severityText" ORDER BY t ASC, "severityText" ASC LIMIT 10000;
SELECT COUNT(*) AS value, date_bin(INTERVAL '1 minute', "eventTime") AS t, "serviceName" FROM otel_logs WHERE upper("severityText") IN ('ERROR', 'WARN', 'WARNING') GROUP BY date_bin(INTERVAL '1 minute', "eventTime"), "serviceName" ORDER BY t ASC, "serviceName" ASC LIMIT 10000;
SELECT * FROM otel_logs WHERE "time" >= '2026-10-15T16:40:00Z' AND "time" <= '2026-10-15T21:40:00Z' AND "severityNumber" >= 17 ORDER BY "time" DESC LIMIT 100;
SELECT "eventTime", "serviceName", "severityText", body FROM otel_logs WHERE regexp_like(body, '(?i)\border\b') AND regexp_like(body, '(?i)\bplaced\b') AND "serviceName" = 'checkout' AND "eventTime" >= '2026-10-15T21:00:00Z' AND "eventTime" < '2026-10-15T21:30:00Z' ORDER BY "eventTime" DESC LIMIT 100;
SELECT COUNT(*) AS c FROM otel_logs WHERE regexp_like(body, '(?i)\bconnect\b') AND regexp_like(body, '(?i)\bredis\b');
SELECT * FROM otel_logs WHERE regexp_like(body, '(?i)\bGET\b') AND "eventTime" >= '2026-10-15T21:00:00Z' AND "eventTime" <= '2026-10-16T06:50:00Z' ORDER BY "eventTime" DESC LIMIT 100;
SELECT "eventTime" AS ts, "serviceName", "severityText", body FROM otel_logs WHERE body ILIKE '%redis%' ORDER BY ts DESC LIMIT 100;
SELECT COUNT(*) AS n, patterns_field FROM (SELECT CASE WHEN body IS NULL OR body = '' THEN '' ELSE regexp_replace(body, '[a-zA-Z0-9]+', '<*>', 'g') END AS patterns_field FROM otel_logs WHERE "serviceName" = 'cart' AND body IS NOT NULL AND NOT (body ILIKE '%ValkeyCartStore%') AND NOT (body ILIKE '%called with userId%')) GROUP BY patterns_field ORDER BY n DESC LIMIT 20;
SELECT COUNT(*) AS n, AVG(d) AS avg_ms, approx_percentile_cont(0.95) WITHIN GROUP (ORDER BY d) AS p95_ms, MAX(d) AS max_ms, method, path FROM (SELECT COALESCE(g[2], '') AS method, COALESCE(g[3], '') AS path, TRY_CAST(g[12] AS INT) AS d FROM (SELECT regexp_match(body, '^\[([^\]]+)\] "(\S+) (\S+) ([^"]+)" (\d{3}) (\S+) (\S+) (\S+) "([^"]*)" (\d+) (\d+) (\d+) [\s\S]+') AS g FROM otel_logs WHERE "serviceName" = 'frontend-proxy')) GROUP BY method, path ORDER BY n DESC, method ASC, path ASC LIMIT 20;
SELECT * FROM otel_logs ORDER BY "eventTime" DESC LIMIT 1000;
SELECT * FROM otel_logs LIMIT 10;
SELECT * FROM otel_logs ORDER BY "eventTime" DESC LIMIT 10;
SELECT * FROM otel_logs WHERE "serviceName" = 'product-reviews' ORDER BY "eventTime" DESC LIMIT 10;
SELECT * FROM otel_logs WHERE "serviceName" = 'kafka' LIMIT 10;
SELECT * FROM otel_logs WHERE "serviceName" = 'product-reviews' AND "eventTime" >= '2026-10-15T23:00:00Z' AND "eventTime" < '2026-10-16T00:35:00Z' LIMIT 10;
SELECT * FROM otel_spans WHERE "durationInNanos" >= 20000000 AND "durationInNanos" <= 200000000 LIMIT 10;
SELECT * FROM otel_spans ORDER BY "durationInNanos" DESC LIMIT 10;
SELECT COUNT(*) AS "count()", date_bin(INTERVAL '1 hour', "eventTime") AS "span(eventTime,1h)" FROM otel_logs GROUP BY date_bin(INTERVAL '1 hour', "eventTime") LIMIT 10000;
SELECT COUNT(*) AS "count()", latency_band FROM (SELECT CASE WHEN "durationInNanos" < 1000000 THEN 'a_lt_1ms' WHEN "durationInNanos" >= 1000000 AND "durationInNanos" < 10000000 THEN 'b_1_10ms' WHEN "durationInNanos" >= 10000000 AND "durationInNanos" < 100000000 THEN 'c_10_100ms' WHEN "durationInNanos" >= 100000000 AND "durationInNanos" < 1000000000 THEN 'd_100ms_1s' WHEN "durationInNanos" >= 1000000000 AND "durationInNanos" < 10000000000 THEN 'e_1_10s' WHEN "durationInNanos" >= 10000000000 THEN 'f_ge_10s' END AS latency_band FROM otel_spans) GROUP BY latency_band LIMIT 10000;
SELECT COUNT(*) AS "count()", "serviceName", kind FROM otel_spans WHERE "eventTime" >= '2026-10-16T02:00:00Z' AND "eventTime" < '2026-10-16T02:10:00Z' GROUP BY "serviceName", kind ORDER BY "count()" DESC LIMIT 10;
SELECT COUNT(*) AS "count()", "serviceName", kind FROM otel_spans WHERE "eventTime" >= '2026-10-16T01:00:00Z' AND "eventTime" < '2026-10-16T01:20:00Z' GROUP BY "serviceName", kind ORDER BY "serviceName" DESC, kind ASC LIMIT 10;
SELECT COUNT(DISTINCT "traceId") AS "dc(traceId)" FROM otel_spans;
SELECT * FROM otel_logs WHERE regexp_like(body, '(?i)\btelescope\b') OR regexp_like(body, '(?i)\bbinoculars\b') OR regexp_like(body, '(?i)\bscore\b') LIMIT 10;
SELECT COUNT(*) AS points, first_value(value ORDER BY "eventTime" DESC) AS last_value, MAX("eventTime") AS last_seen, name FROM otel_metrics WHERE kind = 'GAUGE' GROUP BY name ORDER BY points DESC LIMIT 10;
SELECT COUNT(*) AS spans FROM otel_spans;
SELECT COUNT(*) AS spans, "traceId", "serviceName" FROM otel_spans GROUP BY "traceId", "serviceName" LIMIT 10;
SELECT COUNT(*) AS c, "durationInNanos", "durationInNanos" - 1 AS d1, "durationInNanos" - 2 AS d2, "durationInNanos" - 3 AS d3 FROM otel_spans GROUP BY "durationInNanos", "durationInNanos" - 1, "durationInNanos" - 2, "durationInNanos" - 3 ORDER BY c DESC LIMIT 10;
SELECT COUNT(*) AS pv, date_bin(INTERVAL '1 minute', "startTime") AS minute, name FROM otel_spans WHERE "serviceName" = 'cart' AND name IN ('HGET', 'HMSET', 'EXPIRE', 'POST /oteldemo.CartService/GetCart', 'POST /oteldemo.CartService/AddItem', 'POST /oteldemo.CartService/EmptyCart') AND "startTime" IS NOT NULL GROUP BY name, date_bin(INTERVAL '1 minute', "startTime") ORDER BY pv DESC LIMIT 10 OFFSET 100;
SELECT COUNT(*) AS c, "traceId", CAST(date_part('minute', "startTime") AS INT) AS m, name FROM otel_spans GROUP BY "traceId", CAST(date_part('minute', "startTime") AS INT), name ORDER BY c DESC LIMIT 10;
SELECT AVG(value) AS avg_count FROM (SELECT COUNT(*) AS value FROM otel_spans WHERE "serviceName" = 'frontend' AND "startTime" IS NOT NULL GROUP BY date_bin(INTERVAL '1 minute', "startTime"));
SELECT COUNT(*) AS logs, AVG(character_length(body)) AS avg_len, MAX(character_length(body)) AS max_len, SUM(character_length(body)) AS bytes, "serviceName" FROM otel_logs GROUP BY "serviceName" HAVING COUNT(*) > 1000 ORDER BY bytes DESC LIMIT 10000;
SELECT COUNT(*) AS nonempty_bucket_entries, name FROM (SELECT name, unnest("bucketCountsList") AS bucket FROM otel_metrics WHERE kind = 'HISTOGRAM') WHERE bucket > 0 GROUP BY name ORDER BY nonempty_bucket_entries DESC, name ASC LIMIT 10;
SELECT COUNT(DISTINCT "severityNumber") AS sev_numbers, COUNT(DISTINCT "severityText") AS sev_labels, array_agg(DISTINCT "severityText" ORDER BY "severityText") AS labels, "serviceName", array_to_string(array_agg(DISTINCT "severityText" ORDER BY "severityText"), ',') AS label_list FROM otel_logs GROUP BY "serviceName" HAVING COUNT(DISTINCT "severityText") > 1 ORDER BY sev_labels DESC, "serviceName" ASC LIMIT 10000;
SELECT COUNT(*) AS spans, COUNT(DISTINCT "durationInNanos") AS distinct_durations, "serviceName" FROM otel_spans GROUP BY "serviceName" ORDER BY spans DESC LIMIT 10000;
SELECT COUNT(DISTINCT "time") AS export_timestamps, COUNT(*) AS points, MIN("time") AS first_export, MAX("time") AS last_export, "serviceName" FROM otel_metrics GROUP BY "serviceName" ORDER BY export_timestamps ASC, "serviceName" ASC LIMIT 10000;
SELECT COUNT(*) AS spans, approx_distinct("traceId") AS traces, date_bin(INTERVAL '1 minute', "startTime") AS minute FROM otel_spans WHERE "startTime" IS NOT NULL GROUP BY date_bin(INTERVAL '1 minute', "startTime") ORDER BY minute ASC LIMIT 10000;
